import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Presentación mágica y efectos visuales modulares","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/magic/presentation.md","filePath":"es/game-design/magic/presentation.md"}'),n={name:"es/game-design/magic/presentation.md"};function r(o,e,d,c,l,u){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="magic-presentation-and-modular-vfx" tabindex="-1">Presentación mágica y efectos visuales modulares <a class="header-anchor" href="#magic-presentation-and-modular-vfx" aria-label="Enlace permanente a &quot;Presentación mágica y efectos visuales modulares&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las decisiones enumeradas siguen Sin resolver. Los fundamentos existentes en estado Aceptado conservan su alcance. <strong>Implementación:</strong> no se ha establecido ninguna implementación de gameplay del Batch 04. <strong>Disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo conciliación documental, no validación en ejecución. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04 y al <a href="/Syrolands-Public/es/game-design/magic.html">diseño mágico anterior</a>.</p><p><a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Panorama de magia</a> · <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado y preguntas abiertas</a></p><h2 id="a-reusable-visual-grammar" tabindex="-1">Una gramática visual reutilizable <a class="header-anchor" href="#a-reusable-visual-grammar" aria-label="Enlace permanente a &quot;Una gramática visual reutilizable&quot;">​</a></h2><p>Las combinaciones de variantes necesitan un lenguaje visual escalable que comunique las mecánicas. Los Core Patterns seleccionan una familia visual como proyectil, rayo, explosión, campo, aura, runa, onda o impacto. Los modificadores pueden alterar o superponer tono/color, escala, estela, densidad de partículas, impacto, marca sobre superficies, pulsación, duración, campo residual y sonido. Son requisitos/candidatos de presentación, no pruebas de que el renderizador actual admita esas características.</p><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Lectura visual en estado Propuesto</th></tr></thead><tbody><tr><td>Fireball</td><td>Proyectil de fuego base</td></tr><tr><td>Fireball + Compression</td><td>Proyectil más pequeño/concentrado, estela más densa, impacto más definido</td></tr><tr><td>Fireball + Persistence</td><td>Impacto base más brasas persistentes/campo sobre el suelo</td></tr></tbody></table><p>Una variante comprimida/penetrante debería percibirse como tal; un campo persistente debería persistir visiblemente. Evitar cientos de recursos específicos cuando una composición reutilizable comunique las mismas diferencias. La legibilidad y las respuestas posibles limitan la complejidad visual junto con el modelo acotado de modificadores.</p><h2 id="presentation-is-not-authority" tabindex="-1">La presentación no es autoridad <a class="header-anchor" href="#presentation-is-not-authority" aria-label="Enlace permanente a &quot;La presentación no es autoridad&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Límite</th><th>Ejemplo mágico</th></tr></thead><tbody><tr><td>INTENCIÓN DEL USUARIO</td><td>Solicitar una variante preparada o consultada sobre un objetivo/región</td></tr><tr><td>ESTADO AUTORITATIVO DEL SERVIDOR</td><td>Validar conocimiento, memoria, recursos, tiempos de consulta/lanzamiento, interrupción y efectos reales</td></tr><tr><td>ESTADO SINCRONIZADO</td><td>Solo información aprobada por el servidor adecuada para sus destinatarios; contrato exacto sin resolver</td></tr><tr><td>PRESENTACIÓN DEL CLIENTE</td><td>Lectura del libro, proyectil, impacto, sonido e indicaciones del campo residual</td></tr></tbody></table><p>Los píxeles de sprites, partículas, finalización de animaciones y colisiones del cliente nunca resuelven gameplay ni condicionan resultados del servidor. La duración mostrada debe seguir la vida útil autoritativa mediante un futuro contrato explícito.</p><h2 id="renderer-and-input-constraints" tabindex="-1">Restricciones de renderizador y controles <a class="header-anchor" href="#renderer-and-input-constraints" aria-label="Enlace permanente a &quot;Restricciones de renderizador y controles&quot;">​</a></h2><p>Los efectos existentes de UO, capas de sprites, tonos, animaciones reutilizables, extensiones del cliente, mejoras del renderizador y futuros sistemas de partículas son candidatos. <strong>No se ha elegido ningún proceso de producción.</strong> La composición arbitraria de partículas/shaders y la interacción física con libros en combate no quedan establecidas como capacidades de ClassicUO en este batch.</p><p>Las restricciones del renderizador preservan la coherencia entre dibujo/selección, profundidad, capas de equipo, transparencia y orden de renderizado. El trabajo técnico futuro deberá auditar recursos reales, contratos emisor/receptor y soporte de versiones/alternativas, y después medir legibilidad, tiempos de fotograma, sobredibujado, llamadas de dibujo y memoria en escenas representativas. La accesibilidad, reasignación de controles y dependencia exclusiva del color necesitan revisión de experiencia de uso; ninguna afirmación de rendimiento ni asignación de controles es definitiva.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Límites del renderizador/controles, viabilidad de recursos, representación de variantes, visibilidad/información revelada, accesibilidad, contratos de eventos/esquemas/capacidades/alternativas, límites de presupuesto, sincronización temporal y alcance del prototipo. Este documento no crea ningún identificador de efecto ni asignación de red.</p>',15)])])}const b=a(n,[["render",r]]);export{m as __pageData,b as default};
